// Node Code n8n — "Run Once for All Items"
// Seedance 1.5 Pro — first frame / last frame
const items = $input.all();

const urls = items.map(item => {
  const result = JSON.parse(item.json.data.resultJson);
  return result.resultUrls[0];
});

const splitOutItems = $('Split Out').all();

const output = [];

for (let i = 0; i < urls.length; i++) {
  const isLast = i === urls.length - 1;

  const inputUrls = isLast
    ? [urls[i]]
    : [urls[i], urls[i + 1]];

  const prompt = isLast
    ? "The car drives forward along the coastal road, smooth continuous motion, cinematic side tracking shot."
    : splitOutItems[i].json.animation_prompt;

  output.push({
    json: {
      model: "bytedance/seedance-1.5-pro",
      callBackUrl: "https://your-domain.com/api/callback",
      input: {
        prompt: prompt,
        input_urls: inputUrls,
        aspect_ratio: "16:9",
        resolution: "720p",
        duration: 6,
        generate_audio: false,
        nsfw_checker: true
      }
    }
  });
}

return output;
